type View='discover'|'classes'|'resources'|'requests'|'learning'|'saved'|'teaching'|'certificates'|'profile'|'admin'|'notifications'|'guidelines'|'tutor'|'chat';
type State={backend?:string;providerOrders?:any[];conversations:Conversation[];listings:Listing[];requests:any[];orders:any[];events:any[];marks:any[];reviews:any[];profile:any;signedIn:boolean;userId?:string};
